        },
        "content_en": {
          "type": "custom",
          "tokenizer": "standard",
          "filter": ["lowercase", "english_stem", "asciifolding"]
        }
      }
    }
  },
  "mappings": {
    "properties": {
      "content_pt": {
        "type": "text",
        "analyzer": "content_pt"
      },
      "content_es": {
        "type": "text",
        "analyzer": "content_es"
      },
      "content_en": {
        "type": "text",
        "analyzer": "content_en"
      },
