      }
    }
  }
}

# 4. Indexação com documentos por idioma
def index_multilingual_doc(es_client, doc_id, html_content):
    result = detect_languages_in_document(html_content)

    # Criar documento separado por idioma principal
    for lang in result['document_languages']:
        lang_field = f"content_{lang}"
        doc_body = {
